<template>
  <div :class="status =='carousel' ? 'main-center' : ''" data-app>
    <v-dialog v-model="dialogWord.dialog" width="80%" persistent>
      <v-card>
        <v-card-title style="display: flex; justify-content: center;">Какие буквы изображены?</v-card-title>
        <v-card-text>
          <v-text-field v-model="dialogWord.text"></v-text-field>
        </v-card-text>
        <v-divider></v-divider>
        <v-card-actions>
          <v-btn class="btn-green" @click="confirmDialog()" style="margin-right: 10px">Ответить</v-btn>
          <v-spacer></v-spacer>
          <v-btn class="btn-red" @click="dialogWord.dialog = false">Отмена</v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>

    <v-dialog v-model="dialogFinish.dialog" persistent>
      <v-card>
        <v-card-title style="display: flex; justify-content: center;">
          Порядок фотографий
        </v-card-title>
        <v-card-text style="overflow: scroll; display: flex;">
          <img :src="getImgUrl({name: 'full.jpg', folder: 'Photo5'})" alt="" height="200" width="200">
          <img :src="getImgUrl({name: 'full.jpg', folder: 'Photo10'})" alt="" height="200" width="200">
          <img :src="getImgUrl({name: 'full.jpg', folder: 'Photo7'})" alt="" height="200" width="200">
          <img :src="getImgUrl({name: 'full.jpg', folder: 'Photo11'})" alt="" height="200" width="200">
          <img :src="getImgUrl({name: 'full.jpg', folder: 'Photo1'})" alt="" height="200" width="200">
        </v-card-text>
        <v-divider></v-divider>
        <v-card-actions>
          <v-spacer></v-spacer>
          <v-btn class="btn-red" @click="dialogFinish.dialog = false">Назад</v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>

    <div v-if="status == 'carousel'">
      <div style="display: flex; width: 100vw; overflow: scroll; gap: 10px; margin-top: 10px">
      <v-card @click="openPuzzle(photo)" v-for="photo in photoDone" :key="photo.id" class="card" style="display: flex; flex-direction: column; justify-content: space-between; height: 300px;">
        <v-card-title style="justify-content: center;">
          <img :class="photo.done ? '' : 'imgBlur'" :src="getImgUrl(photo)" alt="" height="150" width="150">
        </v-card-title>
        <v-card-text>
          <img alt="" width="200px">
          <div v-if="photo.done" style="display: flex; justify-content: space-between; flex-direction: column; flex-wrap: wrap; align-content: center; font-size: 40px;">
            <div v-if="photo.wordDone">
              {{ photo.word }}
            </div>
            <div v-else>
              <v-btn class="btn-green" @click="openDialogWord(photo)">Открыть</v-btn>
            </div>
          </div>
          <div style="display: flex; justify-content: center;" v-else>
            <img height="40" :src="getImgUrlSimple('questionIcon.png')" alt="">
          </div>
        </v-card-text>
      </v-card>
      <v-card style="width: 100px; display: flex; align-items: center;">
        <v-btn :disabled="AllPuzzlesDone" @click="Continue()" style="height: 100%;">
          <v-icon size="40">
            mdi-arrow-right-bold
          </v-icon>
        </v-btn>
      </v-card>
    </div>
    </div>

    <template v-if="status == 'puzzle'">
      <v-btn class="btn-red" style="margin-top: 4px; margin-bottom: 10px;" @click="status = 'carousel'">Назад</v-btn>
      <draggable  
        v-model="puzzles"   
        :move="handleMove"
        @end="handleDragEnd"
        delay='60'
        style="width: 246px; position: absolute; left: 0; right: 0; margin: 0 auto; display: flex; flex-direction: row; flex-wrap: wrap; gap: 2px"
      >
        <div v-for="(puzzle, i) of puzzles" :key="i" style="display: inline-block; height: 60px; width: 60px;">
          <template v-if="puzzle.id < 16">
            <div :id="puzzle.id" style="height: 60px; width: 60px; border: 1px solid rgb(181, 181, 181);"></div>
          </template>
          <template v-else>
            <img :id="puzzle.id" :src="getImgUrl(puzzle)" alt="" height="60" width="60">
          </template>
        </div>
        
      </draggable>
    </template>
  </div>
</template>

<script>
import draggable from "vuedraggable";
  export default {
    name: 'Puzzle',
    components: {
      draggable
    },
    data() {
      return {
        dialogFinish: { // диалог где показываются окончательное решение
          dialog: false
        },
        dialogWord: { // диалог с вводом букв в картинку
          dialog: false,
          text: '',
          photoId: null
        },
        status: 'carousel', //carousel -> puzzle -> carousel -> finish
        movingIndex: 0,
        futureIndex: 0,
        dragging: false,
        puzzles: [],
        photoParts: [],
        currentPuzzleId: null,
        photoDone: [
          {
            id: 'photo_1',
            done: false,
            wordDone: false,
            folder: 'Photo1',
            words: ['н', 'д'],
            word: 'Н',
            name: 'full.jpg'
          },
          {
            id: 'photo_2',
            done: false,
            wordDone: false,
            words: [],
            word: 'Пусто',
            folder: 'Photo2',
            name: 'full.jpg'
          },
          {
            id: 'photo_3',
            done: false,
            wordDone: false,
            words: [],
            word: 'Пусто',
            folder: 'Photo3',
            name: 'full.jpg'
          },
          {
            id: 'photo_4',
            done: false,
            wordDone: false,
            words: [],
            word: 'Пусто',
            folder: 'Photo4',
            name: 'full.jpg'
          },
          {
            id: 'photo_5',
            done: false,
            wordDone: false,
            words: ['м', 'д', 'р'],
            word: 'Д',
            folder: 'Photo5',
            name: 'full.jpg'
          },
          {
            id: 'photo_6',
            done: false,
            wordDone: false,
            words: [],
            word: 'Пусто',
            folder: 'Photo6',
            name: 'full.jpg'
          },
          {
            id: 'photo_7',
            done: false,
            wordDone: false,
            words: ['у', 'в'],
            word: 'В',
            folder: 'Photo7',
            name: 'full.jpg'
          },
          {
            id: 'photo_8',
            done: false,
            wordDone: false,
            words: [],
            word: 'Пусто',
            folder: 'Photo8',
            name: 'full.jpg'
          },
          {
            id: 'photo_9',
            done: false,
            wordDone: false,
            words: ['р', 'н', 'у'],
            word: 'Н',
            folder: 'Photo9',
            name: 'full.jpg'
          },
          {
            id: 'photo_10',
            done: false,
            wordDone: false,
            words: ['л', 'и', 'н'],
            word: 'И',
            folder: 'Photo10',
            name: 'full.jpg'
          },
          {
            id: 'photo_11',
            done: false,
            wordDone: false,
            words: ['о', 'и', 'а'],
            word: 'А',
            folder: 'Photo11',
            name: 'full.jpg'
          },
          {
            id: 'photo_12',
            done: false,
            wordDone: false,
            words: ['k'],
            word: 'K',
            folder: 'Photo12',
            name: 'full.jpg'
          },
        ]
      }
    },
    computed: {
      AllPuzzlesDone: function() {
        this.photoDone
        for (let i = 0; i < this.photoDone.length; i++) {
          if (!this.photoDone[i].done) return true;
          if (!this.photoDone[i].wordDone) return true;
        }
          return false;
      }
    },
    watch: {
      puzzles(v) {
        this.check(v);
      }
    },
    methods: {
      Continue() {
        this.dialogFinish.dialog = true;

      },
      openPuzzle(puzzle) {
        if (!puzzle) return;
        if (puzzle.done) return;
        console.log('открыть пазл')

        this.preparePuzzles();
        this.getPhotoParts(puzzle.folder);

        this.currentPuzzleId = puzzle.id;
        this.status = 'puzzle';
      },
      confirmDialog() {
        const photo = this.photoDone.find((i) => i.id == this.dialogWord.photoId);
        const textArr = this.dialogWord.text.split('');
        if (textArr.length != photo.words.length) {
          alert('Введены неверные буквы, попробуй еще раз)');
            return;
        }
        textArr.forEach((textW) => {
          if (!photo.words.includes(textW.toLowerCase())) {
            alert('Введены неверные буквы, попробуй еще раз)');
            return;
          }
        });
        photo.wordDone = true;
        this.dialogWord.dialog = false;
      },
      openDialogWord(photo) {
        this.dialogWord.text = '';
        this.dialogWord.photoId = photo.id;
        this.dialogWord.dialog = true;
      },
      check(arr) {
        const sliceArr = arr.slice(0, 16);
        console.log(sliceArr)
        for (let i = 1; i < 16; i++) {
          if (sliceArr[i].id - sliceArr[i-1].id == 1) {
            if (sliceArr[i].name == 'puzzle_part' || sliceArr[i-1].name == 'puzzle_part') {
              return;
            }
          } else {
            return;
          }
        }

        // собрано правильно
        console.log('правильно')
        this.photoDone.find((i) => i.id == this.currentPuzzleId).done = true;
        this.status = 'carousel';
      },
      getImgUrlSimple(name) {
        const images = require.context('../assets', false, /\.png$/);
        return images('./' + name);
      },
      getImgUrl(img) {
        if (img == '') return null;
        let images = null;
        const ext = img.name.split('.')[1];
        switch (img.folder) {
          case 'Photo1': {
            if (ext == 'png') {
              images = require.context('../assets/puzzle/Photo1', false, /\.png$/);
            } else {
              images = require.context('../assets/puzzle/Photo1', false, /\.jpg$/);
            }
            break;
          }
          case 'Photo2': {
            if (ext == 'png') {
              images = require.context('../assets/puzzle/Photo2', false, /\.png$/);
            } else {
              images = require.context('../assets/puzzle/Photo2', false, /\.jpg$/);
            }
            break;
          }
          case 'Photo3': {
            if (ext == 'png') {
              images = require.context('../assets/puzzle/Photo3', false, /\.png$/);
            } else {
              images = require.context('../assets/puzzle/Photo3', false, /\.jpg$/);
            }
            break;
          }
          case 'Photo4': {
            if (ext == 'png') {
              images = require.context('../assets/puzzle/Photo4', false, /\.png$/);
            } else {
              images = require.context('../assets/puzzle/Photo4', false, /\.jpg$/);
            }
            break;
          }
          case 'Photo5': {
            if (ext == 'png') {
              images = require.context('../assets/puzzle/Photo5', false, /\.png$/);
            } else {
              images = require.context('../assets/puzzle/Photo5', false, /\.jpg$/);
            }
            break;
          }
          case 'Photo6': {
            if (ext == 'png') {
              images = require.context('../assets/puzzle/Photo6', false, /\.png$/);
            } else {
              images = require.context('../assets/puzzle/Photo6', false, /\.jpg$/);
            }
            break;
          }
          case 'Photo7': {
            if (ext == 'png') {
              images = require.context('../assets/puzzle/Photo7', false, /\.png$/);
            } else {
              images = require.context('../assets/puzzle/Photo7', false, /\.jpg$/);
            }
            break;
          }
          case 'Photo8': {
            if (ext == 'png') {
              images = require.context('../assets/puzzle/Photo8', false, /\.png$/);
            } else {
              images = require.context('../assets/puzzle/Photo8', false, /\.jpg$/);
            }
            break;
          }
          case 'Photo9': {
            if (ext == 'png') {
              images = require.context('../assets/puzzle/Photo9', false, /\.png$/);
            } else {
              images = require.context('../assets/puzzle/Photo9', false, /\.jpg$/);
            }
            break;
          }
          case 'Photo10': {
            if (ext == 'png') {
              images = require.context('../assets/puzzle/Photo10', false, /\.png$/);
            } else {
              images = require.context('../assets/puzzle/Photo10', false, /\.jpg$/);
            }
            break;
          }
          case 'Photo11': {
            if (ext == 'png') {
              images = require.context('../assets/puzzle/Photo11', false, /\.png$/);
            } else {
              images = require.context('../assets/puzzle/Photo11', false, /\.jpg$/);
            }
            break;
          }
          case 'Photo12': {
            if (ext == 'png') {
              images = require.context('../assets/puzzle/Photo12', false, /\.png$/);
            } else {
              images = require.context('../assets/puzzle/Photo12', false, /\.jpg$/);
            }
            break;
          }
        }
        if (!images) return '';
        return images('./' + img.name);
      },
      getPhotoParts(folder) {
        this.photoParts = [];
        for (let i = 0; i < 16; i++) {
          this.photoParts.push({
            id: 16 + i,
            folder,
            name: `${i + 1}.png`,
            drag: true
          })
        }

        // перемешиваем
        this.photoParts.sort(() => Math.random() - 0.5);
        
        this.puzzles = this.puzzles.concat(this.photoParts);
      },
      preparePuzzles() {
        this.puzzles = [];
        for (let i = 0; i < 16; i++) {
          this.puzzles.push({
            id: i,
            name: 'puzzle_part',
            drag: false
          })
        }
      },
      handleDragEnd() {
        const currentPart = this.puzzles[this.movingIndex];
        console.log(currentPart)
        if (!currentPart) return;
        if (!currentPart.drag) return;

        this.futureItem = this.puzzles[this.futureIndex];
        this.movingItem = this.puzzles[this.movingIndex];
        const _items = Object.assign([], this.puzzles);
        _items[this.futureIndex] = this.movingItem;
        _items[this.movingIndex] = this.futureItem;

        this.puzzles = _items;
      },
      handleMove(e) { // при помещении на кого то
        const { index, futureIndex } = e.draggedContext;
        this.movingIndex = index;
        this.futureIndex = futureIndex;
        return false;
      }
    },
    mounted() {
    }
  }
</script>

