<template>
  <div style="height: calc(100vh - 80px);">
    <Puzzle v-if="status =='puzzle'"></Puzzle>
    <div v-if="status == 'question'">
      <v-card>
        <v-card-text>
          Заметила необычные вещи на фотографиях?
        </v-card-text>
        <v-card-actions>
          <v-btn class="btn-green" @click="status = 'begin_done'">Да!!!</v-btn>
          <v-spacer></v-spacer>
          <v-btn class="btn-red" @click="status = 'begin_error'">Нет...</v-btn>
        </v-card-actions>
      </v-card>
    </div>
    <Actor :message="current_msg" :emoji="current_emoji" :delay="current_delay"/>
  </div>
</template>

<script>
import Actor from './Actor.vue';
import Puzzle from './Puzzle.vue';

function stop(event) {
  event.currentTarget.acontroller.abort();
}

export default {
  name: 'Arjs',
  components: {
    Actor,
    Puzzle
  },
  data() {
    return {
      status: 'begin', // begin -> scan_baloons_dlg1 -> scan_baloons -> scan_models_dlg1 -> scan_models
      current_msg: '',
      current_emoji: '',
      current_delay: 0,
      status_msgs: {
        'begin': [
          {
            text: 'С днем рождения, Любимая!!!',
            delay: 2420,
            emoji: 'max_4',
          },
          {
            text: 'Вот мы опять встретились с тобой спустя год.',
            delay: 3380,
            emoji: 'max_1',
          },
          {
            text: 'Даааа, выросла то как уже, не узнать))',
            delay: 3000,
            emoji: 'max_1'
          },
          {
            text: 'Ну что же, я думаю, ты понимаешь для чего ты здесь)',
            delay: 3750,
            emoji: 'max_3'
          },
          {
            text: 'Да ладно, нынче будет очень легко)',
            delay: 2650,
            emoji: 'max_3'
          },
          {
            text: 'Необходимо будет всего лишь пособирать пазлы.',
            delay: 3660,
            emoji: 'max_3'
          },
          {
            text: 'Ах да, ты наверно уже обратила внимание на свой классный фото-кубик. Присмотрись внимательно к фотографиям, замечаешь что то необычное?',
            delay: 10740,
            emoji: 'max_3',
            next_status: 'question'
          }
        ],
        'begin_done': [
          {
            text: 'Да, на фотографиях присутствуют рандомные буквы. Правильно собранный пазл подскажет тебе верную букву на фото.',
            delay: 8800,
            emoji: 'max_1',
          },
          {
            text: 'Сделаем это!',
            delay: 1000,
            emoji: 'max_1',
            next_status: 'puzzle'
          }
        ],
        'begin_error': [
          {
            text: 'Как нет?! Смотри внимательнее, иначе так и застрянем на этом моменте...',
            delay: 5590,
            emoji: 'max_3',
            next_status: 'question'
          }
        ],
        'end': [
          {
            text: 'Вот и все, все задания завершены.',
            delay: 2000,
            emoji: 'max_3',
          },
          {
            text: 'С днем рождения, Любимая!!! Пусть этот год принесет тебе море положительных эмоций!',
            delay: 2000,
            emoji: 'max_4',
          }
        ]
      },
    }
  },
  watch: {
    status() {
      this.startDialog();
    }
  },
  methods: {
    timeout_msg(delay) {
      return new Promise(resolve => setTimeout(resolve, delay));
    },
    timeout_click(signal) {
      return new Promise((resolve, reject)=> {
        const error = new DOMException('aborted!', 'AbortError');

        const timeout = setTimeout(() => {
          resolve('you report!'); 
        }, 600000);

        if (signal.aborted) {
          clearTimeout(timeout);
          return reject(error);
        }

        signal.addEventListener('abort',() => {
          clearTimeout(timeout);
          reject(error);
        });
      });
    },
    async startDialog() {
      const messages = this.status_msgs[this.status];
      if (messages == undefined) {
        this.current_msg = '';
        return;
      }

      const msg_elem = document.querySelector('#msg');

      for (let i = 0; i < messages.length; i++) {
        const msg = messages[i];
        msg_elem.removeEventListener('click', stop);
        this.current_msg = msg.text;
        this.current_emoji = msg.emoji;
        this.current_delay = msg.delay;

        await this.timeout_msg(msg.delay);

        console.log('добавлен')
        let acontroller = new AbortController();
        let signal = acontroller.signal;
        msg_elem.addEventListener('click', stop);
        msg_elem.acontroller = acontroller;

        try {
          await this.timeout_click(signal);
        } catch (err) {
          // console.log();
        }

        if (i == messages.length - 1) {
          this.current_msg = '';
        }

        // eslint-disable-next-line no-prototype-builtins
        if (msg.hasOwnProperty('next_status')) {
          this.status = msg.next_status;
        }
      }
    },
  },
  async mounted() {
    // await navigator.mediaDevices.getUserMedia({ 
    //   video: {
    //     facingMode: 'environment'
    //   } 
    // });
    this.startDialog();
  }
}
</script>

